//! The chat's key actions: `Action`, generated by `action_list!` from the files of
//! `key_actions/` (the catalogue's `open_transcript`, `find_transcript`, `open_warnings`,
//! `toggle_voice`, `toggle_side_conversation` and `toggle_raw_output`, and the hardwired
//! `cycle_collaboration_mode`), each with the keys of the keymap the user's `tui.keymap`
//! resolved over the oracle's defaults (`RuntimeKeymap::defaults`: `app`, `chat`, `composer`
//! groups). Only the actions of the chat's hub role are files there: those that open a screen or
//! start history search. The keys of what a feature owns are the feature's (`FeatureView::
//! actions`, `Action::Feature`); the rest (copy, clear terminal, interrupt of a running turn, ...)
//! belong to the slices that own what they act on.

use rtwk::Cx;
use rtwk::focus::KeyPress;

use codex_tui_core::keymap::{ActionId, Keymap};

use super::key_actions::{self, KeyAction, Keyed};
use super::session_page::ChatState;
use crate::features::{self, KeyCx};

/// The enum, its ids, its presses and its dispatch, from the one list.
macro_rules! action_enum {
    ($($file:ident => $variant:ident;)*) => {
        /// What a key of the chat does.
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        pub enum Action {
            $(
            #[doc = concat!("`", stringify!($file), "`, a file of `key_actions/`.")]
            $variant,
            )*
            /// A key a feature owns (`FeatureView::actions`): its keymap action.
            Feature(ActionId),
        }

        impl Action {
            /// The keymap action whose keys do it.
            pub fn id(self) -> ActionId {
                match self {
                    $(Action::$variant => <key_actions::$file::$variant as KeyAction>::ID,)*
                    Action::Feature(id) => id,
                }
            }

            /// What the key does, from the page that bound it.
            pub fn run(self, cx: &mut Cx<'_, ChatState>, keyed: &Keyed<'_>) {
                match self {
                    $(Action::$variant => <key_actions::$file::$variant as KeyAction>::run(cx, keyed),)*
                    Action::Feature(id) => {
                        let thread = rtwk::provider::read::<codex_tui_core::threads::ThreadModel, _>(cx)
                            .id()
                            .clone();
                        let draft = super::composer::submission(keyed.ui);
                        let hs = keyed.hs;
                        let mut say = |intent| {
                            cx.emit(&hs.intent, codex_tui_core::app::Intent::Feature(intent));
                        };
                        features::run_action(id, &mut KeyCx::new(&thread, &draft, &mut say));
                    }
                }
            }
        }

        /// The keys of the actions, in the order of the list, the keys of the features' last.
        pub fn presses(keymap: &Keymap) -> Vec<(Action, KeyPress)> {
            let mut keys = Vec::new();
            $(
            for id in std::iter::once(<key_actions::$file::$variant as KeyAction>::ID)
                .chain(<key_actions::$file::$variant as KeyAction>::ALSO.iter().copied())
            {
                keys.extend(
                    crate::keymap::presses(keymap, id)
                        .into_iter()
                        .map(|key| (Action::$variant, key)),
                );
            }
            )*
            for action in features::actions() {
                for id in std::iter::once(action.id).chain(action.also.iter().copied()) {
                    keys.extend(
                        crate::keymap::presses(keymap, id)
                            .into_iter()
                            .map(|key| (Action::Feature(action.id), key)),
                    );
                }
            }
            keys
        }
    };
}

key_actions::action_list!(action_enum);
